    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(s1, "arc1", { "start" : vector(40, 0) * millimeter, "mid" : vector(28.284271, 28.284271) * millimeter, "end" : vector(0, 40) * millimeter });
    skSolve(s1);
    compositeCurve(context, id + "curve1", { "edges" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE) });
    trimCurve(context, id + "trim1", { "moveBoundaryType" : MoveCurveBoundaryType.EXTEND, "wires" : qCreatedBy(id + "curve1", EntityType.BODY), "flipHeuristics" : false, "helpPoint" : qContainsPoint(qOwnedByBody(qCreatedBy(id + "curve1", EntityType.BODY), EntityType.VERTEX), vector(0, 40, 0) * millimeter), "endCondition" : CurveExtensionEndCondition.BLIND, "extensionDistance" : 10 * millimeter, "extensionShape" : CurveExtensionShape.CURVATURE });
    return { "edges" : wireProbe(context, qCreatedBy(id + "curve1", EntityType.BODY)) };
}
